PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,admin INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS libraries(id TEXT PRIMARY KEY,name TEXT NOT NULL,root_id TEXT NOT NULL,path TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available',last_scan INTEGER,error TEXT);
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'movie',year INTEGER,description TEXT,rating TEXT,duration_seconds INTEGER,poster TEXT,origin TEXT NOT NULL CHECK(origin IN ('local','torrent')),library_id TEXT REFERENCES libraries(id) ON DELETE CASCADE,external_id TEXT,provider_id TEXT,file_key TEXT UNIQUE,scan_generation TEXT);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE,origin TEXT NOT NULL CHECK(origin IN ('local','torrent')),kind TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available',locator TEXT NOT NULL,quality TEXT,size INTEGER,video_codec TEXT,audio_codec TEXT,details TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS sources_media ON sources(media_id);
CREATE INDEX IF NOT EXISTS media_origin ON media(origin,title);
CREATE TABLE IF NOT EXISTS collections(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE,PRIMARY KEY(user_id,media_id));
CREATE TABLE IF NOT EXISTS progress(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE,position REAL NOT NULL,duration REAL NOT NULL,PRIMARY KEY(user_id,media_id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',progress REAL NOT NULL DEFAULT 0,error TEXT,details TEXT NOT NULL DEFAULT '{}',created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,manifest TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available',error TEXT);
CREATE TABLE IF NOT EXISTS secrets(name TEXT PRIMARY KEY,ciphertext TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS playback(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,source_id TEXT NOT NULL,mode TEXT NOT NULL,worker_id TEXT,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS torrents(id TEXT PRIMARY KEY,engine TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',progress REAL NOT NULL DEFAULT 0,details TEXT NOT NULL DEFAULT '{}',updated INTEGER NOT NULL);
INSERT OR IGNORE INTO meta(key,value) VALUES('schema_version','1');
